export const priceOfTruthId = (number: StoryLessonNumber) => `conversational-skills-L5-C5-${number}-${priceOfTruthEpisodes[number].skill}-ja-v1`;

// Authoring replaces text only; any existing artwork remains owned by the editor.
function retainArtwork(original: any, revised: any): any {
  if (!original || !revised || typeof original !== 'object' || typeof revised !== 'object') return revised;
  if (Array.isArray(original) && Array.isArray(revised)) return revised.map((item, i) => retainArtwork(original[i], item));
  for (const [key, value] of Object.entries(original)) {
    if (/image|background/i.test(key)) revised[key] = structuredClone(value);
    else if (key in revised) revised[key] = retainArtwork(value, revised[key]);
  }
  return revised;
}

export function buildPriceOfTruthLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: priceOfTruthEpisodes[number], id: priceOfTruthId(number), chapterName: 'The Price of Truth',
    setting: 'Eastbridge Creative, a fictional marketing agency in Tokyo. The hotel proposal investigation reaches its conclusion; later scenes show a client meeting, team dinner in Shinjuku and a new employee’s first day.',
    previousSummary: index === 0 ? difficultChoicesEpisodes[9].closing : priceOfTruthEpisodes[storyLessonNumbers[index - 1]!].closing,
    storyNotes: `${conversationalLanguageInstructions(5)}\nUser reference: The Price of Truth, the final Tokyo After Hours chapter. Map eight episodes to 1-4 and 6-9; 5/10 remain dynamic checkpoints. Short tutor-first dialogue, direct named roles, Japanese support, standard guides and fixed feedback. No new images or romance. Reveal only facts known at this episode. Link route is confirmed in Lesson 1, notice received two months before review appears in Lesson 2, forecast motive is confirmed in Lesson 3, knowledge admitted and suspension pending final decision in Lesson 4. Formal dismissals, Ethan's warning/training and continued client consideration occur in Lesson 8; the fresh-evaluation contract win is only three months later in Lesson 9. Do not equate notice, intent, account ownership, actual access and sharing. Do not invent proof of Kuroda intending delivery to a rival bid team, the link creator, criminal findings, compensation, a promotion or future chapter. The ending is reflection and welcoming a new employee, not a required speech.`,
  });
  lesson.storyData.storyTitle = 'Tokyo After Hours';
  lesson.storyData.characters = [
    { id: 'mika', name: 'Mika Tanaka', role: 'main', description: 'Marketing worker from Osaka. She asks careful questions and helps the team communicate honestly.' },
    { id: 'ethan', name: 'Ethan', role: 'supporting', description: 'Project manager from Bristol. His handling of outside sharing and team disagreements is central to this chapter.' },
    { id: 'soo-jin', name: 'Soo-jin', role: 'supporting', description: 'Creative director from Seoul. She supports open discussion and leads the creative work.' },
    { id: 'daichi', name: 'Daichi', role: 'supporting', description: 'Senior analyst. He checks the forecasts and explains the financial review.' },
    { id: 'sato', name: 'Ms. Sato', role: 'supporting', description: 'Information security specialist. She presents the route, earlier email and investigation findings in sequence.' },
    { id: 'kuroda', name: 'Director Kuroda', role: 'supporting', description: 'Director whose outside review and financial decisions are being checked. Use only findings available in the current episode.' },
  ];
  lesson.learnData.steps[0].discussionPart.tutorSteps[2].tip = 'Use the supplied character details. Accept short answers and a simple reason.';
  lesson.stepBData.grammarTip.tutorSteps[1].tip = 'Use one simple example from this scene. Correct one important error if needed.';
  if (number === 7) {
    lesson.applyData.tutorSteps[0].scripts[0].text = "I'll be the hotel representative. Please be Mika. Is it clear? I'll start.";
    lesson.missionData.tutorSteps[1].scripts[0].text = "I'll be the hotel representative. Please be Mika. You may use the useful language. I'll start.";
  }
  if (number === 9) lesson.missionData.tutorSteps[1].scripts[0].text = "I'll be the new employee. Please be Mika. You may use the useful language. I'll start.";
  return retainArtwork(previous, { ...previous, ...lesson, course: 'conversational-skills', level: 5, chapter: 5, lessonNumber: number, levelBadge: 'ELEMENTARY', chapterLabel: 'Chapter 5: The Price of Truth', status: previous.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja', authoringLanguageTarget: 'TOEIC 225-545', authoringLanguageRevision: 'toeic-v1' });
}

export function buildPriceOfTruthChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildPriceOfTruthLesson(number, {}, reference));
}
